    private static byte[] svgToPng(byte[] svgBytes) throws TranscoderException {
        PNGTranscoder transcoder = new PNGTranscoder();
        ByteArrayInputStream svgIn = new ByteArrayInputStream(svgBytes);
        ByteArrayOutputStream pngOut = new ByteArrayOutputStream();
        TranscoderInput input = new TranscoderInput(svgIn);
        TranscoderOutput output = new TranscoderOutput(pngOut);
        transcoder.transcode(input,output);
        return pngOut.toByteArray();
    }
